query getMyPlaceProfile {
  user {
    partnerHashedIdNo
    myplace {
      profile {
        imageUrl
        borderImageUrl
        myplaceId
        myplaceNickname
      }
    }
  }
}

query bookingDetails($input: AccommodationBookingDetailsInput) {
  accommodationBookingDetails(input: $input) {
    ...AccommodationBookingDetails
  }
}

fragment AccommodationBookingDetails on AccommodationBookingDetails {
  roomTotal
  siteDesc
  agencyName
  images
  businessTypeId
  rooms {
    reprUrl
    resrvUrl
    drtOptionList {
      iconName
      optionName
    }
    isBookable
    isMatching
    bookingType
    resocId
    resocName

query getVisitorReviews($input: VisitorReviewsInput) {
  visitorReviews(input: $input) {
    items {
      id
      cursor
      reviewId
      rating
      author {
        id
        nickname
        from
        imageUrl
        borderImageUrl
        objectId
        url
        review {
          totalCount
          imageCount
          avgRating
        }
        theme {
          totalCount
        }
        isFollowing
        followerC

query getVisitorReviewStats($id: String, $itemId: String, $businessType: String = "place") {
  visitorReviewStats(input: { businessId: $id, itemId: $itemId, businessType: $businessType }) {
    id
    name
    apolloCacheId
    review {
      avgRating
      totalCount
      scores {
        count
        score
      }
      starDistribution {
        count
        score
      }
      imageReviewCount
      authorCount
      maxSingleReviewScoreCount

